  m=w.visitMethod(Opcodes.ACC_PUBLIC,p.getProperty("blockIdMethod"),p.getProperty("blockIdDescriptor"),null,null);m.visitCode();m.visitFieldInsn(Opcodes.GETSTATIC,self,"blockId","I");m.visitInsn(Opcodes.IRETURN);m.visitMaxs(0,0);m.visitEnd();
